const messages = $json.messages || [];

return messages
  .map(m => {
    const msg = m.message || {};
    const level = Number(msg.level || 0);
    const originalMessage = String(msg.message || "");
    const text = originalMessage.toLowerCase();

    let severity = null;
    let authStatus = null;
    let incidentType = null;

    // 1. Authentication detection
    if (
      text.includes("failed password") ||
      text.includes("authentication failure") ||
      text.includes("invalid user") ||
      text.includes("login failed") ||
      text.includes("failed publickey") ||
      text.includes("pam authentication error") ||
      text.includes("user not known")
    ) {
      authStatus = "AUTH_FAIL";
      severity = "WARNING";
      incidentType = "AUTHENTICATION_FAILURE";
    } else if (
      text.includes("accepted password") ||
      text.includes("accepted publickey") ||
      text.includes("login successful") ||
      text.includes("session opened") ||
      text.includes("authentication succeeded")
    ) {
      authStatus = "AUTH_SUCCESS";
      incidentType = "AUTHENTICATION_SUCCESS";
    }

    // 2. Hardware errors: CRITICAL
    const hardwareError =
      /\b(hardware error|machine check exception|mce error|uncorrectable ecc|ecc memory error|memory failure|disk failure|disk error|i\/o error|raid failure|smart failure|cpu failure|power supply failure|fan failure|overheating|thermal shutdown|kernel hardware error)\b/i.test(
        originalMessage
      );

    if (hardwareError) {
      severity = "CRITICAL";
      incidentType = "HARDWARE_ERROR";
    }

    // 3. Network intrusion / foreign-country indicators: CRITICAL
    // Requires an explicit country/location or geo-IP indicator in the log.
    const foreignCountryIntrusion =
      /\b(foreign country|foreign-country|geoip.*(country|foreign)|country.*(unexpected|unauthorized|blocked)|connection from .* (outside|foreign)|intrusion detected|network intrusion|unauthorized remote access|malicious inbound connection|command and control|c2 beacon)\b/i.test(
        originalMessage
      );

    if (foreignCountryIntrusion) {
      severity = "CRITICAL";
      incidentType = "NETWORK_INTRUSION";
    }

    // 4. Critical application errors: CRITICAL
    const criticalApplicationError =
      /\b(application critical|critical application|fatal exception|fatal error|application crash|service crashed|segmentation fault|uncaught exception|out of memory|database corruption|transaction log corruption|application unavailable|service unavailable|failed to start .*service|panic:)\b/i.test(
        originalMessage
      );

    if (criticalApplicationError) {
      severity = "CRITICAL";
      incidentType = "CRITICAL_APPLICATION_ERROR";
    }

    // 5. Preserve existing general severity rules when no stronger
    // specific classification has already been assigned.
    if (!severity) {
      if (level >= 4) {
        severity = "CRITICAL";
        incidentType = "SYSLOG_CRITICAL";
      } else if (level === 3) {
        severity = "WARNING";
        incidentType = "SYSLOG_WARNING";
      }
    }

    // Include only critical, warning, and authentication events.
    if (!severity && !authStatus) {
      return null;
    }

    return {
      json: {
        timestamp: msg.timestamp || null,
        host: msg.source || "unknown",
        level,
        severity: severity || authStatus,
        auth_status: authStatus,
        incident_type: incidentType || "GENERAL_LOG",
        message: originalMessage
      }
    };
  })
  .filter(Boolean);

