const grouped = {};

for (const item of items) {
  const data = item.json || {};

  // Match the fields shown in your n8n screenshot
  const host = String(data.host || 'unknown');
  const severity = String(data.severity || 'INFO').toUpperCase();
  const authStatus = String(data.auth_status || 'NONE').toUpperCase();
  const incidentType = String(data.incident_type || 'GENERAL').toUpperCase();

  // Your incoming message is a plain string
  const message =
    typeof data.message === 'string'
      ? data.message
      : JSON.stringify(data.message || '');

  const timestamp = data.timestamp || null;
  const level = Number(data.level ?? 0);

  // Group by host, severity, authentication, and incident type
  const key = JSON.stringify([
    host,
    severity,
    authStatus,
    incidentType
  ]);

  if (!grouped[key]) {
    grouped[key] = {
      host: host,
      severity: severity,
      auth_status: authStatus === 'NONE' ? null : authStatus,
      incident_type: incidentType,
      count: 0,
      first_timestamp: timestamp,
      last_timestamp: timestamp,
      messages: [],
      timestamps: [],
      levels: []
    };
  }

  const group = grouped[key];

  group.count++;

  if (message) {
    // Keep a maximum of 50 sample messages per group
    if (group.messages.length < 50) {
      group.messages.push(message);
    }
  }

  if (timestamp) {
    if (group.timestamps.length < 50) {
      group.timestamps.push(timestamp);
    }

    const currentTime = Date.parse(timestamp);
    const firstTime = Date.parse(group.first_timestamp || '');
    const lastTime = Date.parse(group.last_timestamp || '');

    if (
      Number.isFinite(currentTime) &&
      (!Number.isFinite(firstTime) || currentTime < firstTime)
    ) {
      group.first_timestamp = timestamp;
    }

    if (
      Number.isFinite(currentTime) &&
      (!Number.isFinite(lastTime) || currentTime > lastTime)
    ) {
      group.last_timestamp = timestamp;
    }
  }

  if (group.levels.length < 50) {
    group.levels.push(level);
  }
}

// Output one item for each group
return Object.values(grouped).map(group => ({
  json: group
}));

let html = `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; font-family:Arial; font-size:12px;">
<tr style="background:#f2f2f2">
<th>Host</th>
<th>Severity</th>
<th>Auth Status</th>
<th>Count</th>
<th>Sample Messages</th>
</tr>`;

items.forEach(i => {

  let color = 'black';

  if (i.json.severity === 'CRITICAL') {
    color = 'red';
  } else if (i.json.severity === 'WARNING') {
    color = 'orange';
  } else if (i.json.auth_status === 'AUTH_FAIL') {
    color = 'darkred';
  } else if (i.json.auth_status === 'AUTH_SUCCESS') {
    color = 'green';
  }

  html += `<tr>
<td>${i.json.host}</td>
<td style="color:${color}; font-weight:bold;">${i.json.severity}</td>
